AssistantMessageToolRequest(name='create', tool_call_id='toolu_vrtx_01HoNo7HdYQxPNq7X7LQbYXs', arguments={'file_text': ':root {
  --bg: #0b0c0f;
  --bg-elev: #131418;
  --bg-elev-2: #1a1c22;
  --bg-elev-3: #22252d;
  --line: #2a2d36;
  --line-strong: #3a3e4a;
  --text: #ececef;
  --text-muted: #a8acb8;
  --text-dim: #7c818f;
  --accent: #e8b56b;
  --accent-strong: #f4c477;
  --accent-ink: #1a1306;
  --danger: #ff6b6b;
  --success: #6bd4a8;
  --focus: #9bd4ff;
  --radius: 14px;
  --radius-sm: 8px;
  --shadow: 0 6px 24px rgba(0,0,0,.45);
  --maxw: 1240px;
  --gap: clamp(1rem, 2vw, 1.5rem);
}

* { box-sizing: border-box; }
html { scroll-behavior: smooth; }
body {
  margin: 0;
  background: var(--bg);
  color: var(--text);
  font-family: 'Inter', system-ui, -apple-system, Segoe UI, Roboto, Helvetica, Arial, sans-serif;
  font-size: 16px;
  line-height: 1.55;
  -webkit-font-smoothing: antialiased;
  text-rendering: optimizeLegibility;
}

img, svg { display: block; max-width: 100%; }

a { color: var(--text); text-decoration: none; }
a:hover { color: var(--accent-strong); }

h1, h2, h3, h4 { font-family: 'Fraunces', 'Iowan Old Style', Georgia, serif; font-weight: 600; letter-spacing: -.01em; line-height: 1.15; margin: 0; }
h1 { font-size: clamp(2.4rem, 5.5vw, 4.4rem); }
h2 { font-size: clamp(1.6rem, 2.6vw, 2.2rem); }
h3 { font-size: 1.15rem; }
p { margin: 0; }

.wrap { max-width: var(--maxw); margin: 0 auto; padding: 0 clamp(1rem, 3vw, 2rem); }

.visually-hidden {
  position: absolute !important;
  width: 1px; height: 1px;
  padding: 0; margin: -1px;
  overflow: hidden; clip: rect(0,0,0,0);
  white-space: nowrap; border: 0;
}

.skip-link {
  position: absolute; left: 1rem; top: -100px;
  background: var(--accent); color: var(--accent-ink);
  padding: .65rem 1rem; border-radius: var(--radius-sm);
  font-weight: 600; z-index: 100;
  transition: top .15s;
}
.skip-link:focus { top: 1rem; color: var(--accent-ink); }

/* Focus */
:focus-visible {
  outline: 2px solid var(--focus);
  outline-offset: 3px;
  border-radius: 4px;
}

.eyebrow {
  font-size: .72rem;
  letter-spacing: .18em;
  text-transform: uppercase;
  color: var(--text-muted);
  margin: 0 0 .65rem;
  font-weight: 600;
}
.muted { color: var(--text-muted); }
.accent { color: var(--accent); font-style: italic; }

/* ---------- HEADER ---------- */
.site-header {
  position: sticky; top: 0; z-index: 50;
  background: rgba(11,12,15,.85);
  backdrop-filter: blur(14px);
  -webkit-backdrop-filter: blur(14px);
  border-bottom: 1px solid var(--line);
}
.header-wrap {
  display: flex; align-items: center; gap: 2rem;
  height: 68px;
}
.brand { display: inline-flex; align-items: center; gap: .55rem; font-weight: 700; letter-spacing: .14em; }
.brand-mark { color: var(--accent); font-size: 1.4rem; }
.brand-name { font-size: .95rem; }

.primary-nav { flex: 1; }
.primary-nav ul { display: flex; gap: 1.75rem; list-style: none; padding: 0; margin: 0; }
.primary-nav a {
  font-size: .92rem; color: var(--text-muted);
  padding: .5rem 0; position: relative;
}
.primary-nav a:hover, .primary-nav a:focus-visible { color: var(--text); }
.primary-nav a::after {
  content: ''; position: absolute; left: 0; right: 100%; bottom: 2px;
  height: 1px; background: var(--accent); transition: right .25s;
}
.primary-nav a:hover::after { right: 0; }

.header-actions { display: flex; gap: .35rem; align-items: center; }
.icon-btn {
  display: inline-flex; align-items: center; justify-content: center;
  width: 40px; height: 40px;
  border-radius: 50%;
  background: transparent; border: 1px solid transparent;
  color: var(--text); cursor: pointer; position: relative;
  transition: background .15s, border-color .15s;
}
.icon-btn:hover { background: var(--bg-elev-2); border-color: var(--line); }
.cart-count {
  position: absolute; top: 2px; right: 2px;
  background: var(--accent); color: var(--accent-ink);
  font-size: .68rem; font-weight: 700;
  min-width: 18px; height: 18px; border-radius: 9px;
  display: inline-flex; align-items: center; justify-content: center;
  padding: 0 5px;
}
.cart-count.bump { animation: bump .3s ease; }
@keyframes bump { 50% { transform: scale(1.3); } }

.search-panel {
  border-top: 1px solid var(--line);
  background: var(--bg-elev);
  padding: 1rem 0;
}
.search-panel form { display: flex; gap: .75rem; }
.search-panel input {
  flex: 1; background: var(--bg-elev-2); border: 1px solid var(--line);
  color: var(--text); padding: .75rem 1rem; border-radius: var(--radius-sm);
  font-size: 1rem;
}
.search-panel input:focus { outline-color: var(--focus); border-color: var(--line-strong); }

/* ---------- BUTTONS ---------- */
.btn {
  display: inline-flex; align-items: center; justify-content: center;
  gap: .5rem;
  padding: .85rem 1.4rem;
  font-size: .92rem; font-weight: 600;
  border-radius: 999px;
  border: 1px solid transparent;
  cursor: pointer; text-align: center;
  transition: transform .12s, background .15s, border-color .15s, color .15s;
}
.btn:active { transform: translateY(1px); }
.btn-primary { background: var(--accent); color: var(--accent-ink); }
.btn-primary:hover { background: var(--accent-strong); color: var(--accent-ink); }
.btn-ghost { background: transparent; color: var(--text); border-color: var(--line-strong); }
.btn-ghost:hover { background: var(--bg-elev-2); color: var(--text); }

/* ---------- HERO ---------- */
.hero {
  position: relative;
  background:
    radial-gradient(1100px 600px at 75% 25%, rgba(232,181,107,.15), transparent 60%),
    radial-gradient(800px 500px at 10% 90%, rgba(80,120,200,.12), transparent 60%),
    var(--bg);
  border-bottom: 1px solid var(--line);
  overflow: hidden;
}
.hero-wrap {
  display: grid; grid-template-columns: 1.1fr 1fr;
  gap: 3rem; align-items: center;
  padding: clamp(3.5rem, 8vw, 6rem) clamp(1rem, 3vw, 2rem);
}
.hero-copy h1 { margin: .5rem 0 1.2rem; }
.hero .lede { font-size: 1.1rem; color: var(--text-muted); max-width: 46ch; margin-bottom: 1.8rem; }
.hero-cta { display: flex; gap: .75rem; flex-wrap: wrap; margin-bottom: 2.5rem; }
.hero-meta {
  list-style: none; padding: 0; margin: 0;
  display: flex; flex-wrap: wrap; gap: 1.25rem 2rem;
  font-size: .85rem; color: var(--text-muted);
}
.hero-meta li { position: relative; padding-left: 1.2rem; }
.hero-meta li::before {
  content: '✓'; position: absolute; left: 0; color: var(--accent); font-weight: 700;
}

.hero-art {
  position: relative;
  aspect-ratio: 1/1;
  min-height: 320px;
}
.hero-orb {
  position: absolute; inset: 10% 10%;
  border-radius: 50%;
  background:
    radial-gradient(circle at 30% 30%, #3a3225 0%, #1a1612 45%, #0f0c08 75%);
  box-shadow: inset 0 0 80px rgba(0,0,0,.6), 0 30px 80px rgba(0,0,0,.5);
  border: 1px solid var(--line);
}
.hero-card {
  position: absolute;
  background: var(--bg-elev-2);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem;
  display: grid; grid-template-columns: 48px 1fr auto; align-items: center; gap: .8rem;
  font-size: .88rem;
  box-shadow: var(--shadow);
  min-width: 240px;
  backdrop-filter: blur(6px);
}
.hero-card strong { color: var(--accent); font-weight: 600; }
.hero-card-1 { left: -2%; top: 12%; animation: float 6s ease-in-out infinite; }
.hero-card-2 { right: -2%; bottom: 12%; animation: float 7s ease-in-out -2s infinite; }
@keyframes float { 50% { transform: translateY(-8px); } }
.swatch {
  width: 48px; height: 48px; border-radius: 10px;
  border: 1px solid var(--line);
}
.swatch-onyx { background: linear-gradient(135deg, #2b2d36, #14151a); }
.swatch-ember { background: linear-gradient(135deg, #b97a2c, #6a3d10); }

@media (prefers-reduced-motion: reduce) {
  .hero-card-1, .hero-card-2 { animation: none; }
  html { scroll-behavior: auto; }
}

/* ---------- SECTION HEAD ---------- */
.section-head {
  display: flex; justify-content: space-between; align-items: end;
  gap: 1rem; flex-wrap: wrap;
  margin-bottom: 2rem;
}
.link-arrow {
  color: var(--text-muted); font-size: .9rem; font-weight: 500;
  display: inline-flex; align-items: center; gap: .35rem;
  border-bottom: 1px solid transparent;
}
.link-arrow:hover { color: var(--accent); border-color: var(--accent); }

/* ---------- CATEGORIES ---------- */
.categories { padding: 4rem 0 2rem; }
.cat-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(160px, 1fr));
  gap: var(--gap);
}
.cat-grid a {
  display: flex; flex-direction: column; align-items: center; justify-content: center;
  gap: .5rem;
  padding: 1.6rem 1rem;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  text-align: center;
  transition: transform .2s, background .2s, border-color .2s;
}
.cat-grid a:hover {
  background: var(--bg-elev-2); border-color: var(--line-strong);
  transform: translateY(-2px); color: var(--text);
}
.cat-icon { font-size: 1.7rem; color: var(--accent); }
.cat-name { font-weight: 600; font-size: .95rem; }
.cat-count { font-size: .78rem; color: var(--text-dim); }

/* ---------- FEATURED ---------- */
.featured { padding: 4rem 0; }
.filter-tabs {
  display: inline-flex; padding: 4px;
  background: var(--bg-elev); border: 1px solid var(--line);
  border-radius: 999px;
}
.filter-tabs button {
  background: transparent; border: 0; color: var(--text-muted);
  padding: .55rem 1.1rem; border-radius: 999px;
  font-size: .85rem; font-weight: 600; cursor: pointer;
  transition: background .15s, color .15s;
}
.filter-tabs button:hover { color: var(--text); }
.filter-tabs button[aria-selected="true"] {
  background: var(--bg-elev-3); color: var(--text);
}
.product-grid {
  list-style: none; padding: 0; margin: 0;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--gap);
}
.product {
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: flex; flex-direction: column;
  transition: transform .2s, border-color .2s;
}
.product:hover { transform: translateY(-3px); border-color: var(--line-strong); }
.product-art {
  position: relative;
  aspect-ratio: 4/5;
  overflow: hidden;
}
.product-art .gradient {
  position: absolute; inset: 0;
}
.product-art .glyph {
  position: absolute; inset: 0;
  display: grid; place-items: center;
  font-size: 4rem; color: rgba(255,255,255,.18);
}
.product-badge {
  position: absolute; top: .8rem; left: .8rem;
  background: var(--bg);
  border: 1px solid var(--line-strong);
  color: var(--text);
  font-size: .68rem; letter-spacing: .12em; text-transform: uppercase;
  font-weight: 700;
  padding: .3rem .55rem; border-radius: 4px;
}
.product-badge.new { background: var(--accent); color: var(--accent-ink); border-color: transparent; }
.product-badge.sale { background: #b9433f; color: #fff; border-color: transparent; }

.wishlist {
  position: absolute; top: .6rem; right: .6rem;
  width: 36px; height: 36px; border-radius: 50%;
  background: rgba(11,12,15,.7); border: 1px solid var(--line);
  color: var(--text); cursor: pointer;
  display: grid; place-items: center;
  transition: background .15s, color .15s;
}
.wishlist:hover, .wishlist[aria-pressed="true"] { color: var(--accent); background: var(--bg-elev-2); }

.product-body { padding: 1rem 1.1rem 1.1rem; display: flex; flex-direction: column; gap: .35rem; flex: 1; }
.product-cat { font-size: .72rem; color: var(--text-dim); letter-spacing: .12em; text-transform: uppercase; }
.product-name { font-family: inherit; font-size: 1rem; font-weight: 600; }
.product-name a { color: var(--text); }
.product-name a:hover { color: var(--accent-strong); }
.product-rating { display: flex; align-items: center; gap: .4rem; font-size: .78rem; color: var(--text-muted); }
.stars { color: var(--accent); letter-spacing: 1px; }
.product-foot {
  margin-top: auto; padding-top: .8rem;
  display: flex; justify-content: space-between; align-items: center;
}
.price { font-weight: 600; }
.price .now { color: var(--text); }
.price .was { color: var(--text-dim); margin-left: .4rem; font-weight: 400; font-size: .9em; }
.add-btn {
  background: var(--bg-elev-3); color: var(--text);
  border: 1px solid var(--line);
  padding: .45rem .8rem; border-radius: 999px;
  font-size: .8rem; font-weight: 600; cursor: pointer;
  transition: background .15s, color .15s, border-color .15s;
}
.add-btn:hover { background: var(--accent); color: var(--accent-ink); border-color: transparent; }

/* ---------- DEALS ---------- */
.deals {
  padding: 4rem 0;
  background:
    linear-gradient(180deg, transparent, rgba(232,181,107,.03)),
    var(--bg);
  border-top: 1px solid var(--line);
  border-bottom: 1px solid var(--line);
}
.countdown {
  display: inline-flex; align-items: baseline; gap: .25rem;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  padding: .55rem .9rem;
  border-radius: 10px;
  font-variant-numeric: tabular-nums;
}
.cd-num {
  font-weight: 700; font-size: 1.05rem;
  color: var(--accent);
  min-width: 1.6ch; text-align: center;
}
.cd-lbl { color: var(--text-muted); font-size: .75rem; margin-right: .4rem; }
.cd-lbl:last-child { margin-right: 0; }

.deals-grid {
  display: grid;
  grid-template-columns: 1.2fr 1fr;
  gap: var(--gap);
}
.deal-feature {
  position: relative;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  display: grid; grid-template-rows: 220px 1fr;
}
.deal-tag {
  position: absolute; top: 1rem; left: 1rem; z-index: 2;
  background: var(--accent); color: var(--accent-ink);
  font-weight: 700; padding: .45rem .75rem; border-radius: 6px;
  font-size: .85rem; letter-spacing: .04em;
}
.deal-art {
  background-image:
    radial-gradient(800px 200px at 80% 80%, rgba(232,181,107,.25), transparent 60%);
}
.deal-feature .deal-art { width: 100%; height: 100%; }
.deal-body { padding: 1.5rem 1.6rem 1.8rem; display: flex; flex-direction: column; gap: .7rem; }
.deal-body h3 { font-size: 1.6rem; }
.deal-body .btn { align-self: flex-start; margin-top: .4rem; }
.deal-body .price .now { color: var(--accent); font-size: 1.15rem; }

.deal-list { list-style: none; padding: 0; margin: 0; display: grid; gap: var(--gap); }
.deal-item {
  display: grid; grid-template-columns: 100px 1fr auto; gap: 1rem;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  padding: 1rem;
  align-items: center;
}
.deal-item-art {
  width: 100px; height: 100px; border-radius: 10px;
  border: 1px solid var(--line);
  display: grid; place-items: center;
  font-size: 2rem; color: rgba(255,255,255,.25);
}
.deal-item h3 { font-family: inherit; font-size: 1rem; font-weight: 600; margin-bottom: .25rem; }
.deal-item .price .now { color: var(--accent); }
.deal-item .pct {
  display: inline-block; background: rgba(232,181,107,.15); color: var(--accent);
  font-size: .72rem; font-weight: 700; letter-spacing: .04em;
  padding: .2rem .5rem; border-radius: 4px;
  margin-left: .4rem;
}

/* ---------- EDITORIAL ---------- */
.editorial { padding: 5rem 0 4rem; }
.ed-grid {
  display: grid;
  grid-template-columns: 1.4fr 1fr 1fr;
  grid-template-rows: auto auto;
  gap: var(--gap);
}
.ed-lead { grid-row: span 2; }
.ed-link {
  display: block;
  background: var(--bg-elev);
  border: 1px solid var(--line);
  border-radius: var(--radius);
  overflow: hidden;
  height: 100%;
  transition: border-color .2s, transform .2s;
}
.ed-link:hover { border-color: var(--line-strong); transform: translateY(-2px); color: var(--text); }
.ed-art {
  aspect-ratio: 16/9;
  display: grid; place-items: center;
  position: relative;
  overflow: hidden;
}
.ed-lead .ed-art { aspect-ratio: 4/5; }
.ed-glyph { font-size: 5rem; color: rgba(255,255,255,.2); }
.ed-art-1 { background: linear-gradient(140deg, #2a1f12 0%, #110d08 70%); }
.ed-art-2 { background: linear-gradient(140deg, #1a2532 0%, #0c1018 70%); }
.ed-art-3 { background: linear-gradient(140deg, #2a1a1f 0%, #14090d 70%); }
.ed-art-4 { background: linear-gradient(140deg, #1d2a20 0%, #0c130d 70%); }
.ed-body { padding: 1.3rem 1.4rem 1.5rem; }
.ed-body h3 { font-size: 1.15rem; margin-bottom: .5rem; }
.ed-lead .ed-body h3 { font-size: 1.6rem; margin-bottom: .8rem; }
.ed-lead .ed-body { padding: 1.8rem; }
.byline { font-size: .8rem; color: var(--text-dim); margin-top: .8rem; }

/* ---------- NEWSLETTER ---------- */
.newsletter {
  padding: 4rem 0 5rem;
  border-top: 1px solid var(--line);
  background:
    radial-gradient(600px 300px at 50% 0%, rgba(232,181,107,.06), transparent 60%),
    var(--bg);
}
.nl-wrap {
  display: grid; grid-template-columns: 1fr 1fr; gap: 3rem;
  align-items: center;
}
.nl-wrap h2 { margin-bottom: .8rem; }
.nl-form { display: grid; gap: .9rem; }
.field { display: grid; gap: .35rem; }
.field label {
  font-size: .82rem; color: var(--text-muted); font-weight: 600;
  letter-spacing: .04em;
}
.field input {
  background: var(--bg-elev); border: 1px solid var(--line);
  color: var(--text);
  padding: .85rem 1rem; border-radius: var(--radius-sm);
  font-size: 1rem;
}
.field input:focus { border-color: var(--line-strong); }
.field input[aria-invalid="true"] { border-color: var(--danger); }
.field-help { font-size: .78rem; color: var(--text-dim); margin: 0; }
.nl-status { font-size: .9rem; min-height: 1.2em; }
.nl-status.ok { color: var(--success); }
.nl-status.err { color: var(--danger); }
.nl-form .btn { justify-self: start; }

/* ---------- FOOTER ---------- */
.site-footer {
  background: #08090b;
  border-top: 1px solid var(--line);
  padding-top: 3rem;
  color: var(--text-muted);
}
.footer-wrap {
  display: grid;
  grid-template-columns: 1.6fr repeat(3, 1fr);
  gap: 2rem;
  padding-bottom: 2.5rem;
}
.footer-brand .brand { margin-bottom: .8rem; }
.footer-brand p { max-width: 32ch; font-size: .9rem; }
.foot-title {
  font-family: inherit;
  font-size: .78rem; letter-spacing: .15em;
  text-transform: uppercase; color: var(--text); font-weight: 700;
  margin: 0 0 1rem;
}
.site-footer ul { list-style: none; padding: 0; margin: 0; display: grid; gap: .55rem; font-size: .9rem; }
.site-footer a { color: var(--text-muted); }
.site-footer a:hover { color: var(--accent); }
.footer-base {
  border-top: 1px solid var(--line);
  padding: 1.2rem 0;
  display: flex; justify-content: space-between; align-items: center; gap: 1rem;
  font-size: .82rem; color: var(--text-dim);
  flex-wrap: wrap;
}
.footer-base ul { display: flex; gap: 1.2rem; }

/* ---------- RESPONSIVE ---------- */
@media (max-width: 960px) {
  .primary-nav { display: none; }
  .hero-wrap { grid-template-columns: 1fr; }
  .hero-art { min-height: 360px; }
  .deals-grid { grid-template-columns: 1fr; }
  .deal-feature { grid-template-rows: 180px 1fr; }
  .ed-grid { grid-template-columns: 1fr 1fr; }
  .ed-lead { grid-row: auto; grid-column: span 2; }
  .nl-wrap { grid-template-columns: 1fr; gap: 1.5rem; }
  .footer-wrap { grid-template-columns: 1fr 1fr; }
}
@media (max-width: 560px) {
  .header-wrap { gap: .75rem; height: 60px; }
  .brand-name { display: none; }
  .hero-card { min-width: 200px; padding: .8rem; }
  .hero-meta { gap: .8rem 1.4rem; font-size: .8rem; }
  .ed-grid { grid-template-columns: 1fr; }
  .ed-lead { grid-column: auto; }
  .deal-item { grid-template-columns: 64px 1fr; row-gap: .5rem; }
  .deal-item-art { width: 64px; height: 64px; font-size: 1.3rem; }
  .deal-item .add-btn { grid-column: 1 / -1; justify-self: stretch; text-align: center; }
  .footer-wrap { grid-template-columns: 1fr; gap: 1.5rem; }
  .filter-tabs { width: 100%; overflow-x: auto; }
  .section-head { align-items: flex-start; }
}

/* Forced colors */
@media (forced-colors: active) {
  .btn, .icon-btn, .add-btn, .cat-grid a, .product, .deal-feature, .deal-item, .ed-link, .field input {
    border: 1px solid ButtonBorder;
  }
  .btn-primary, .cart-count, .deal-tag { background: ButtonText; color: ButtonFace; }
  .accent, .cd-num, .product-name a:hover, .price .now, .deal-body .price .now { color: LinkText; }
  .skip-link { background: Highlight; color: HighlightText; }
}
