+// ---------- Countdown ----------
+const cdEnd = new Date();
+cdEnd.setDate(cdEnd.getDate() + 3);
+cdEnd.setHours(23, 59, 59, 0);
+const cdEls = {
+  d: document.getElementById('cdDays'),
+  h: document.getElementById('cdHours'),
+  m: document.getElementById('cdMins'),
+  s: document.getElementById('cdSecs'),
+};
+function pad(n) { return String(Math.max(0, n)).padStart(2, '0'); }
+function tick() {
+  const ms = cdEnd - new Date();
+  if (ms <= 0) { cdEls.d.textContent = cdEls.h.textContent = cdEls.m.textContent = cdEls.s.textContent = '00'; return; }
+  const s = Math.floor(ms / 1000);
+  cdEls.d.textContent = pad(Math.floor(s / 86400));
+  cdEls.h.textContent = pad(Math.floor((s % 86400) / 3600));
+  cdEls.m.textContent = pad(Math.floor((s % 3600) / 60));
+  cdEls.s.textContent = pad(s % 60);
+}
+tick();
